  if (ST.bats.length < 2 && Math.random() < dt / 20) { const f = free(); if (f.length) ST.bats.push(pick(f)); }
  if (ST.shp.length < 2 && Math.random() < dt / 25) { const f = free(); if (f.length) ST.shp.push(pick(f)); }
