  if (ST.exit) for (const p of c) if (!p.bot && inR(p, ESC) && !plS(p.k).d) { endNight(true, 'escape', p.k); return; }
  if (allOut()) { endNight(false, 'Усіх схопили… Зміна закінчилась раніше, ніж ви.'); return; }
