      const pl0 = put(o, mesh(new THREE.ConeGeometry(.12, .4, 3), '#FFFFFF', false), 0, 1.16, 0); pl0.rotation.x = P2; pl0.scale.set(1, 1, .25);
      box(.72, .05, .05, bulb('#E8F4FF'), 0, .45, .24, false);
