      for (let k = 0; k < 3; k++) put(o, mesh(flat(new THREE.CylinderGeometry(.06, .07, .3, 8)), mat('#4F9F5B', { transparent: true, opacity: .85 }), false), -.22 + k * .16, .73, 0);
