      for (const [i, c] of CABS.entries()) if (near(c.s, 1.2)) return { l: c.k === 'desk' ? '🫥 Сховатися під столом' : c.k === 'wc' ? '🚽 Сховатися в кабінці' : c.k === 'pod' ? '🛌 Сховатися в капсулі для сну' : '🫥 Сховатися в шафі', fn: () => req('hide', { i }) };
